<template><div data-ui-id="today-bars" class="hourly-chart" role="list"><button v-for="(bucket,i) in buckets" :key="bucket.hourStart||i" class="hour-bar" :class="{selected:selected===bucket.hourStart}" :style="{height:`${height(bucket.totalTokens)}%`}" :title="tooltip(bucket)" @click="$emit('select',bucket.hourStart)" :aria-label="tooltip(bucket)"><span/></button></div></template>
<script setup>import {computed} from 'vue';const p=defineProps({buckets:{type:Array,default:()=>[]},selected:String});defineEmits(['select']);const peak=computed(()=>Math.max(1,...p.buckets.map(x=>x.totalTokens||0)));const height=x=>Math.max(3,(x/peak.value)*100);const tooltip=x=>`${x.hourStart||'小时未知'} · ${x.totalTokens??'—'} tokens`</script>
